joi_block.script:
hold_ticks := 0
if (all(#FloorLamp).motionSensor_motion ==| false) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 60) {
(#FloorLamp).switch_off()
        break
}
}
else {
hold_ticks = 0
}

